#include <iostream>
#include <cmath>
int main() {
  int a = 10, b = 5, c = 2;
  // Without parentheses - uses standard operator precedence
  int result1 = a + b * c; // result1 will be 20 (5*2 + 10)
  std::cout << "Result without parentheses: " << result1 << std::endl;
  //With parentheses - explicit order of operations
  int result2 = (a + b) * c; // result2 will be 30 ((10+5)*2)
  std::cout << "Result with parentheses: " << result2 << std::endl;
  //Example with function calls and complex expressions
  double x = 2.5, y = 3.7;
  double result3 = std::pow(x + y, 2); // (x+y) is evaluated before pow
  std::cout << "Result with function and parenthesis: " << result3 << std::endl;
  return 0;
}
